import com.franchiseguide.app.model.*
fun main(args:Array<String>){var n=0;fun ok(s:String,b:Boolean){check(b){s};n++;println("PASS $s")};fun bad(s:String,f:()->Unit){ok(s,runCatching(f).isFailure)}
 val d=FranchiseDefinition("custom-space","Space Saga",listOf("Space Saga"),listOf("Star Fleet"),custom=true)
 fun item(k:MediaKind,id:Int,title:String="Space Saga $id")=MediaItem("fixture-${k.name}-$id",kind=k,title=title,source=if(k==MediaKind.BOOK)"openlibrary" else if(k==MediaKind.GAME)"rawg" else "tmdb",sourceId=if(k==MediaKind.BOOK)"/works/OL${id}W" else id.toString(),added=false)
 fun state()=FranchiseRules.State(emptyList(),emptyList(),listOf(d))
 var s=FranchiseScanRules.create(d);ok("four cursors",s.categories.size==4)
 s=FranchiseScanRules.accept(s,MediaKind.SHOW,FranchiseScanRules.current(s,MediaKind.SHOW),FranchiseScanRules.Page(listOf(item(MediaKind.SHOW,1)),false));ok("independent pages",s.categories.getValue(MediaKind.SHOW).items.size==1&&s.categories.getValue(MediaKind.MOVIE).page==0)
 val c=FranchiseScanRules.current(s,MediaKind.GAME);s=FranchiseScanRules.failed(s,MediaKind.GAME,c,"503");ok("retry cursor retained",FranchiseScanRules.current(s,MediaKind.GAME)==c)
 var terms=FranchiseScanRules.create(d,setOf(MediaKind.SHOW));terms=FranchiseScanRules.accept(terms,MediaKind.SHOW,FranchiseScanRules.current(terms,MediaKind.SHOW),FranchiseScanRules.Page(listOf(item(MediaKind.SHOW,1)),false));terms=FranchiseScanRules.accept(terms,MediaKind.SHOW,FranchiseScanRules.current(terms,MediaKind.SHOW),FranchiseScanRules.Page(listOf(item(MediaKind.SHOW,1,"Star Fleet changed")),false));ok("cross-term duplicate",terms.categories.getValue(MediaKind.SHOW).items.size==1&&terms.categories.getValue(MediaKind.SHOW).duplicates==1)
 val candidate=item(MediaKind.SHOW,1);ok("known identity",FranchiseScanRules.classify(candidate,state().copy(media=listOf(candidate.copy(added=true)))).status=="added");ok("ambiguous identity",FranchiseScanRules.classify(candidate,state().copy(media=listOf(candidate.copy(source="tvmaze",sourceId="99",added=true)))).status=="ambiguous")
 var batch=FranchiseScanRules.create(d,setOf(MediaKind.SHOW,MediaKind.BOOK));batch=FranchiseScanRules.accept(batch,MediaKind.SHOW,FranchiseScanRules.current(batch,MediaKind.SHOW),FranchiseScanRules.Page(listOf(candidate.copy(watched=true,plays=5,userNote="remote",progressCurrent=8,progressTotal=9)),false));batch=FranchiseScanRules.accept(batch,MediaKind.BOOK,FranchiseScanRules.current(batch,MediaKind.BOOK),FranchiseScanRules.Page(listOf(item(MediaKind.BOOK,3).copy(trackingStatus="completed",playtimeMinutes=90)),false));batch=FranchiseScanRules.selectAvailable(batch,MediaKind.SHOW,state());batch=FranchiseScanRules.selectAvailable(batch,MediaKind.BOOK,state());val plan=FranchiseScanRules.plan(batch,state(),emptyList(),d);ok("sanitized atomic suggestions",plan.inserted==2&&plan.state.media.isEmpty()&&plan.state.suggestions.all{it.isSuggestion&&!it.added&&!it.watched&&it.plays==0&&it.userNote==null&&it.progressCurrent==0&&it.progressTotal==0&&it.trackingStatus==null})
 bad("stale known blocks batch"){FranchiseScanRules.plan(batch,state().copy(media=listOf(item(MediaKind.BOOK,3).copy(added=true))),emptyList(),d)};bad("changed definition blocks commit"){FranchiseScanRules.plan(batch,state(),emptyList(),d.copy(aliases=listOf("Changed")))}
 args.firstOrNull()?.let{java.io.File(it).writeText(listOf(s.categories.getValue(MediaKind.SHOW).items.size,plan.inserted,plan.state.suggestions.count{it.kind==MediaKind.SHOW},plan.state.suggestions.count{it.kind==MediaKind.BOOK},plan.state.suggestions.sumOf{it.plays},plan.state.suggestions.sumOf{it.progressTotal}).joinToString(","))}
 println("$n FranchiseScanRules assertions passed; no Android UI/runtime claim")}
